for (const pass of [1, 2]) {
  if (!writer.runId) throw new Error("writer did not return a retained run id");
  writer = await runs.run("followup-" + pass, { resume: writer.runId, task: "Revisit pass " + pass + ": " + writer.output });
}
return writer;
```

