  options: {
    laneId: "<manifest-run-id>",
    handoffPath: "/path/to/handoff.json",
    supersession: {
      supersededBy: "<replacement-lane-id>",
      attestedBy: "operator",
      attestedAt: "2026-08-27T16:23:00.000Z"
